initJs:
function(container, apiUrl, tables) {
  // テーブルインデックス
  const STORES_TABLE = 1; // 店舗マスタ
  const PRODUCTS_TABLE = 2; // 商品マスタ
  const DEMAND_FORECAST_TABLE = 9; // 需要予測結果
  const ORDER_TABLE = 10; // 発注データ

  let currentOrderData = [];
  let storesData = [];
  let productsData = [];
  let demandForecastData = [];

  // エラー表示関数
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.classList.remove('hidden');
    setTimeout(() => {
      errorDiv.classList.add('hidden');
    }, 5000);
  }

  // 成功メッセージ表示関数
  function showSuccess(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.style.background = 'rgba(40, 167, 69, 0.1)';
    errorDiv.style.borderColor = '#28a745';
    errorDiv.style.color = '#28a745';
    errorDiv.textContent = message;
    errorDiv.classList.remove('hidden');
    setTimeout(() => {
      errorDiv.classList.add('hidden');
      errorDiv.style.background = 'rgba(220, 53, 69, 0.1)';
      errorDiv.style.borderColor = '#dc3545';
      errorDiv.style.color = '#dc3545';
    }, 3000);
  }

  // 発注テーブル再描画関数
  function renderOrderRows(orders) {
    const tbody = container.querySelector('#order-tbody');

    if (!orders || orders.length === 0) {
      tbody.innerHTML = '<tr><td colspan="9" style="text-align: center; color: var(--text-muted); padding: 40px;">該当する商品がありません</td></tr>';
      updateTotalAmount();
      return;
    }

    tbody.innerHTML = orders.map(order => {
      const product = productsData.find(p => p.id === order.productId) || {};
      const forecast = demandForecastData.find(f => f.商品ID === order.productId) || {};
      const orderAmount = (order.orderQuantity || 0) * (product.単価 || 0);

      return `
        <tr data-id="${order.id || ''}">
          <td>${product.商品コード || ''}</td>
          <td>${product.商品名 || ''}</td>
          <td style="text-align: right;">${forecast.予測数量 || 0}</td>
          <td style="text-align: right;">${forecast.推奨発注数量 || 0}</td>
          <td style="text-align: right;">${order.currentStock || 0}</td>
          <td>
            <input type="number" 
                   class="input order-quantity-input" 
                   data-product-id="${order.productId}"
                   value="${order.orderQuantity || ''}" 
                   min="0" 
                   max="999999"
                   style="width: 100px; text-align: right;">
          </td>
          <td style="text-align: right;">¥${(product.単価 || 0).toLocaleString()}</td>
          <td style="text-align: right;" class="order-amount">¥${orderAmount.toLocaleString()}</td>
          <td>
            <button class="action-btn secondary remove-btn" data-product-id="${order.productId}">削除</button>
          </td>
        </tr>
      `;
    }).join('');

    // 発注数量入力のイベントリスナー
    tbody.querySelectorAll('.order-quantity-input').forEach(input => {
      input.addEventListener('input', handleQuantityChange);
      input.addEventListener('blur', handleQuantityBlur);
    });

    updateTotalAmount();
    updateApprovalButton();
  }

  // 発注数量変更処理
  function handleQuantityChange(e) {
    const input = e.target;
    const productId = input.dataset.productId;
    const quantity = parseInt(input.value) || 0;

    // バリデーション
    if (input.value && !/^\d+$/.test(input.value)) {
      showError('発注数量は数値を入力してください');
      return;
    }

    if (quantity < 0) {
      showError('発注数量は正の値を入力してください');
      input.value = 0;
      return;
    }

    if (quantity > 999999) {
      showError('発注数量は999,999以下で入力してください');
      input.value = 999999;
      return;
    }

    // 発注データ更新
    const orderIndex = currentOrderData.findIndex(o => o.productId === productId);
    if (orderIndex >= 0) {
      currentOrderData[orderIndex].orderQuantity = quantity;
    }

    // 金額計算
    const product = productsData.find(p => p.id === productId);
    const amount = quantity * (product?.単価 || 0);
    const row = input.closest('tr');
    const amountCell = row.querySelector('.order-amount');
    amountCell.textContent = `¥${amount.toLocaleString()}`;

    updateTotalAmount();
    updateApprovalButton();
  }

  // 発注数量フィールドのblur処理
  function handleQuantityBlur(e) {
    const input = e.target;
    if (input.value === '') {
      input.value = 0;
      handleQuantityChange(e);
    }
  }

  // 合計金額更新
  function updateTotalAmount() {
    const total = currentOrderData.reduce((sum, order) => {
      const product = productsData.find(p => p.id === order.productId);
      return sum + ((order.orderQuantity || 0) * (product?.単価 || 0));
    }, 0);

    container.querySelector('#total-amount').textContent = `合計金額: ¥${total.toLocaleString()}`;
  }

  // 承認ボタンの有効/無効切り替え
  function updateApprovalButton() {
    const approveBtn = container.querySelector('#btn-approve');
    const hasOrders = currentOrderData.some(order => (order.orderQuantity || 0) > 0);
    const storeSelected = container.querySelector('#store-select').value;
    const dateSelected = container.querySelector('#order-date').value;

    approveBtn.disabled = !hasOrders || !storeSelected || !dateSelected;
  }

  // 店舗選択肢を設定
  async function loadStores() {
    storesData = await window.aivicApi.list(STORES_TABLE) || [];
    const storeSelect = container.querySelector('#store-select');
    storeSelect.innerHTML = '<option value="">店舗を選択してください</option>' +
      storesData.filter(store => store.有効フラグ).map(store => 
        `<option value="${store.id}">${store.店舗名}</option>`
      ).join('');
  }

  // 商品カテゴリ選択肢を設定
  async function loadCategories() {
    productsData = await window.aivicApi.list(PRODUCTS_TABLE) || [];
    const categories = [...new Set(productsData.map(p => p.商品カテゴリID).filter(Boolean))];
    const categorySelect = container.querySelector('#category-filter');
    categorySelect.innerHTML = '<option value="">全てのカテゴリ</option>' +
      categories.map(cat => `<option value="${cat}">カテゴリ${cat}</option>`).join('');
  }

  // 需要予測データ読み込み
  async function loadDemandForecast() {
    demandForecastData = await window.aivicApi.list(DEMAND_FORECAST_TABLE) || [];
  }

  // 発注データ表示
  async function displayOrderData() {
    const storeId = container.querySelector('#store-select').value;
    const orderDate = container.querySelector('#order-date').value;
    const categoryFilter = container.querySelector('#category-filter').value;

    if (!storeId) {
      showError('店舗を選択してください');
      return;
    }

    // 現在日付チェック
    if (orderDate && new Date(orderDate) < new Date().setHours(0,0,0,0)) {
      showError('発注日付には本日以降の日付を選択してください');
      return;
    }

    // 商品データをフィルタリング
    let filteredProducts = productsData.filter(p => p.有効フラグ && p.AI予測対象フラグ);
    if (categoryFilter) {
      filteredProducts = filteredProducts.filter(p => p.商品カテゴリID === categoryFilter);
    }

    // 発注データ作成
    currentOrderData = filteredProducts.map(product => {
      const forecast = demandForecastData.find(f => 
        f.店舗ID === storeId && 
        f.商品ID === product.id &&
        (!orderDate || f.予測対象日 === orderDate)
      ) || {};

      return {
        id: `temp_${product.id}`,
        productId: product.id,
        storeId: storeId,
        orderQuantity: 0,
        currentStock: Math.floor(Math.random() * 100), // 仮の在庫数
        forecastQuantity: forecast.予測数量 || 0,
        recommendedQuantity: forecast.推奨発注数量 || 0
      };
    });

    renderOrderRows(currentOrderData);
  }

  // 推奨発注数量で一括入力
  function bulkInputRecommended() {
    if (currentOrderData.length === 0) {
      showError('発注データを表示してから実行してください');
      return;
    }

    if (!confirm('推奨発注数量で一括入力しますか？現在の入力内容は上書きされます。')) {
      return;
    }

    currentOrderData.forEach(order => {
      order.orderQuantity = order.recommendedQuantity || 0;
    });

    renderOrderRows(currentOrderData);
    showSuccess('推奨発注数量で一括入力しました');
  }

  // 承認処理
  async function approveOrder() {
    const storeId = container.querySelector('#store-select').value;
    const orderDate = container.querySelector('#order-date').value;

    if (!storeId) {
      showError('店舗が選択されていません');
      return;
    }

    if (!orderDate) {
      showError('発注日付が選択されていません');
      return;
    }

    const ordersToApprove = currentOrderData.filter(order => (order.orderQuantity || 0) > 0);

    if (ordersToApprove.length === 0) {
      showError('発注数量を入力してください');
      return;
    }

    // 承認確認ダイアログ表示
    const dialog = container.querySelector('#approval-dialog');
    const summary = container.querySelector('#approval-summary');

    const totalAmount = ordersToApprove.reduce((sum, order) => {
      const product = productsData.find(p => p.id === order.productId);
      return sum + (order.orderQuantity * (product?.単価 || 0));
    }, 0);

    summary.innerHTML = `
      <div>発注店舗: ${storesData.find(s => s.id === storeId)?.店舗名 || ''}</div>
      <div>発注日付: ${orderDate}</div>
      <div>発注商品数: ${ordersToApprove.length}件</div>
      <div>合計金額: ¥${totalAmount.toLocaleString()}</div>
    `;

    dialog.classList.remove('hidden');
  }

  // 承認実行
  async function executeApproval() {
    const storeId = container.querySelector('#store-select').value;
    const orderDate = container.querySelector('#order-date').value;
    const ordersToApprove = currentOrderData.filter(order => (order.orderQuantity || 0) > 0);

    try {
      for (const order of ordersToApprove) {
        const product = productsData.find(p => p.id === order.productId);
        const orderData = {
          店舗ID: storeId,
          商品ID: order.productId,
          発注日: orderDate,
          納期予定日: new Date(Date.now() + 3 * 24 * 60 * 60 * 1000).toISOString().split('T')[0], // 3日後
          発注数量: order.orderQuantity,
          予測数量: order.forecastQuantity,
          発注単価: product?.単価 || 0,
          発注金額: order.orderQuantity * (product?.単価 || 0),
          発注方法: 'AI推奨採用',
          発注ステータス: '承認済み',
          仕入先ID: product?.仕入先ID || '',
          発注理由: 'AI需要予測に基づく発注',
          承認者ID: 'current-user-id',
          承認日時: new Date().toISOString(),
          自動発注フラグ: false,
          作成者ID: 'current-user-id',
          更新者ID: 'current-user-id'
        };

        await window.aivicApi.save(ORDER_TABLE, orderData);
      }

      container.querySelector('#approval-dialog').classList.add('hidden');
      showSuccess(`${ordersToApprove.length}件の発注が正常に承認されました`);

      // データリセット
      currentOrderData = [];
      renderOrderRows([]);
      container.querySelector('#store-select').value = '';
      container.querySelector('#order-date').value = '';
      container.querySelector('#category-filter').value = '';

    } catch (error) {
      showError('発注承認処理でエラーが発生しました');
    }
  }

  // 初期化処理
  async function initialize() {
    // 今日の日付を設定
    const today = new Date().toISOString().split('T')[0];
    container.querySelector('#order-date').value = today;

    await Promise.all([
      loadStores(),
      loadCategories(),
      loadDemandForecast()
    ]);
  }

  // イベントリスナー設定
  container.querySelector('#btn-display').addEventListener('click', displayOrderData);
  container.querySelector('#btn-update-prediction').addEventListener('click', async () => {
    await loadDemandForecast();
    await displayOrderData();
    showSuccess('需要予測結果を更新しました');
  });
  container.querySelector('#btn-bulk-input').addEventListener('click', bulkInputRecommended);
  container.querySelector('#btn-approve').addEventListener('click', approveOrder);
  container.querySelector('#btn-cancel').addEventListener('click', () => {
    if (confirm('入力内容をクリアしますか？')) {
      currentOrderData = [];
      renderOrderRows([]);
      container.querySelector('#store-select').value = '';
      container.querySelector('#order-date').value = new Date().toISOString().split('T')[0];
      container.querySelector('#category-filter').value = '';
    }
  });

  // 承認ダイアログのイベントリスナー
  container.querySelector('#btn-approval-ok').addEventListener('click', executeApproval);
  container.querySelector('#btn-approval-cancel').addEventListener('click', () => {
    container.querySelector('#approval-dialog').classList.add('hidden');
  });

  // 行レベル操作のイベントデリゲーション
  container.addEventListener('click', async (e) => {
    const removeBtn = e.target.closest('.remove-btn');
    if (removeBtn) {
      const productId = removeBtn.dataset.productId;
      if (confirm('この商品を発注リストから削除しますか？')) {
        currentOrderData = currentOrderData.filter(order => order.productId !== productId);
        renderOrderRows(currentOrderData);
        showSuccess('商品を発注リストから削除しました');
      }
    }
  });

  // 店舗・日付・カテゴリ変更時の承認ボタン更新
  container.querySelector('#store-select').addEventListener('change', updateApprovalButton);
  container.querySelector('#order-date').addEventListener('change', updateApprovalButton);

  // 初期化実行
  initialize();
}
